CREATE TABLE store_snapshot (
  actor_id TEXT PRIMARY KEY CHECK (actor_id <> ''),
  machine TEXT NOT NULL CHECK (machine <> ''),
  status TEXT NOT NULL CHECK (status IN ('active', 'done', 'stopped')),
  snapshot TEXT NOT NULL CHECK (json_valid(snapshot)),
  saved_at INTEGER NOT NULL
) STRICT;

CREATE TABLE store_snapshot_state (
  actor_id TEXT NOT NULL REFERENCES store_snapshot (actor_id) ON DELETE CASCADE,
  machine TEXT NOT NULL,
  state_path TEXT NOT NULL CHECK (state_path <> ''),
  PRIMARY KEY (actor_id, state_path)
) STRICT, WITHOUT ROWID;

CREATE INDEX store_snapshot_state_by_path ON store_snapshot_state (machine, state_path, actor_id);

CREATE TABLE store_errored_snapshot (
  actor_id TEXT PRIMARY KEY CHECK (actor_id <> ''),
  machine TEXT NOT NULL CHECK (machine <> ''),
  snapshot TEXT NOT NULL CHECK (json_valid(snapshot)),
  event_id TEXT,
  saved_at INTEGER NOT NULL
) STRICT;

CREATE TABLE store_inbox (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id TEXT NOT NULL CHECK (event_id <> ''),
  actor_id TEXT NOT NULL CHECK (actor_id <> ''),
  topic TEXT NOT NULL CHECK (topic <> ''),
  payload TEXT NOT NULL CHECK (json_valid(payload)),
  received_at INTEGER NOT NULL,
  consumed_at INTEGER,
  UNIQUE (actor_id, event_id)
) STRICT;

CREATE INDEX store_inbox_pending ON store_inbox (actor_id, sequence) WHERE consumed_at IS NULL;

CREATE TABLE store_deadline (
  deadline_id INTEGER PRIMARY KEY AUTOINCREMENT,
  actor_id TEXT NOT NULL CHECK (actor_id <> ''),
  state_path TEXT NOT NULL CHECK (state_path <> ''),
  event_name TEXT NOT NULL CHECK (event_name <> ''),
  fire_at INTEGER NOT NULL,
  entry_id TEXT NOT NULL CHECK (entry_id <> ''),
  fired_at INTEGER,
  UNIQUE (actor_id, state_path, event_name)
) STRICT;

CREATE INDEX store_deadline_due ON store_deadline (fire_at, actor_id) WHERE fired_at IS NULL;

ALTER TABLE store_deadline RENAME TO store_deadline_old;
DROP INDEX store_deadline_due;
CREATE TABLE store_deadline (
  deadline_id INTEGER PRIMARY KEY AUTOINCREMENT,
  actor_id TEXT NOT NULL CHECK (actor_id <> ''),
  state_path TEXT NOT NULL,
  event_name TEXT NOT NULL CHECK (event_name <> ''),
  fire_at INTEGER NOT NULL,
  entry_id TEXT NOT NULL CHECK (entry_id <> ''),
  fired_at INTEGER,
  UNIQUE (actor_id, state_path, event_name)
) STRICT;
INSERT INTO store_deadline SELECT * FROM store_deadline_old;
UPDATE sqlite_sequence SET seq = max(seq, coalesce((SELECT seq FROM sqlite_sequence WHERE name = 'store_deadline_old'), 0)) WHERE name = 'store_deadline';
INSERT INTO sqlite_sequence(name, seq) SELECT 'store_deadline', seq FROM sqlite_sequence WHERE name = 'store_deadline_old' AND NOT EXISTS (SELECT 1 FROM sqlite_sequence WHERE name = 'store_deadline');
DROP TABLE store_deadline_old;
CREATE INDEX store_deadline_due ON store_deadline (fire_at, actor_id) WHERE fired_at IS NULL;

CREATE TABLE store_migration_failure (
  actor_id TEXT PRIMARY KEY CHECK (actor_id <> ''),
  from_machine TEXT NOT NULL CHECK (from_machine <> ''),
  to_machine TEXT NOT NULL CHECK (to_machine <> ''),
  kind TEXT NOT NULL CHECK (kind IN ('version-invalid', 'restore-mismatch', 'gate-missing', 'token-return', 'token-trap', 'no-path', 'mapping-failed', 'mapping-timeout', 'context-rejected', 'store')),
  message TEXT NOT NULL,
  detail TEXT NOT NULL CHECK (json_valid(detail)),
  failed_at INTEGER NOT NULL
) STRICT;

CREATE INDEX store_migration_failure_by_target ON store_migration_failure (to_machine, actor_id);

CREATE TABLE bundle (
  digest TEXT PRIMARY KEY CHECK (length(digest) = 64 AND digest NOT GLOB '*[^0-9a-f]*'),
  recorded_at INTEGER NOT NULL
) STRICT;

CREATE TABLE bundle_file (
  digest TEXT NOT NULL REFERENCES bundle (digest),
  path TEXT NOT NULL CHECK (substr(CAST(path AS BLOB), 1, 11) = CAST('blueprints/' AS BLOB)),
  text TEXT NOT NULL,
  PRIMARY KEY (digest, path)
) STRICT;

CREATE TRIGGER bundle_immutable BEFORE UPDATE ON bundle
BEGIN
  SELECT RAISE(ABORT, 'bundle rows are immutable');
END;

CREATE TRIGGER bundle_kept BEFORE DELETE ON bundle
BEGIN
  SELECT RAISE(ABORT, 'bundle rows are never deleted');
END;

CREATE TRIGGER bundle_file_immutable BEFORE UPDATE ON bundle_file
BEGIN
  SELECT RAISE(ABORT, 'bundle_file rows are immutable');
END;

CREATE TRIGGER bundle_file_kept BEFORE DELETE ON bundle_file
BEGIN
  SELECT RAISE(ABORT, 'bundle_file rows are never deleted');
END;

-- ---
-- relationships:
--   realizes: github-source-database-schema
-- ---
-- SQLite schema of the tables the GitHub event source owns in Manifold's
-- database file, beside the store's and the router's tables and migrated
-- under the owner github.

CREATE TABLE github_delivery (
  delivery_id TEXT PRIMARY KEY CHECK (delivery_id <> ''),
  hook_id INTEGER NOT NULL CHECK (hook_id > 0),
  event TEXT NOT NULL,
  received_at INTEGER NOT NULL
) STRICT, WITHOUT ROWID;

CREATE TABLE github_redelivery (
  delivery_id TEXT PRIMARY KEY CHECK (delivery_id <> ''),
  hook_id INTEGER NOT NULL CHECK (hook_id > 0),
  attempt_id INTEGER NOT NULL,
  requested_at INTEGER NOT NULL
) STRICT, WITHOUT ROWID;

CREATE TABLE github_hook_scan (
  hook_id INTEGER PRIMARY KEY CHECK (hook_id > 0),
  scanned_through INTEGER NOT NULL
) STRICT;

CREATE TABLE github_pending (
  kind TEXT NOT NULL CHECK (kind IN ('issue', 'item', 'project')),
  node_id TEXT NOT NULL CHECK (node_id <> ''),
  requested_at INTEGER NOT NULL,
  generation INTEGER NOT NULL CHECK (generation > 0),
  project_node_id TEXT,
  PRIMARY KEY (kind, node_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX github_pending_requested ON github_pending (requested_at);

CREATE TABLE github_project (
  project_node_id TEXT PRIMARY KEY CHECK (project_node_id <> ''),
  owner TEXT NOT NULL CHECK (owner <> ''),
  number INTEGER NOT NULL CHECK (number > 0),
  closed INTEGER NOT NULL CHECK (closed IN (0, 1)),
  revision INTEGER NOT NULL CHECK (revision >= 0)
) STRICT, WITHOUT ROWID;

CREATE UNIQUE INDEX github_project_owner_number
  ON github_project (owner COLLATE NOCASE, number);

CREATE TABLE github_item (
  item_node_id TEXT PRIMARY KEY CHECK (item_node_id <> ''),
  project_node_id TEXT NOT NULL,
  content_type TEXT NOT NULL
    CHECK (content_type IN ('issue', 'pull-request', 'draft-issue')),
  content_node_id TEXT NOT NULL,
  present INTEGER NOT NULL CHECK (present IN (0, 1)),
  archived INTEGER NOT NULL CHECK (archived IN (0, 1)),
  revision INTEGER NOT NULL CHECK (revision >= 0)
) STRICT, WITHOUT ROWID;

CREATE INDEX github_item_project ON github_item (project_node_id);
CREATE INDEX github_item_content ON github_item (content_node_id);

CREATE TABLE github_field_value (
  item_node_id TEXT NOT NULL,
  field_node_id TEXT NOT NULL,
  field_name TEXT NOT NULL,
  value TEXT CHECK (value IS NULL OR json_valid(value)),
  revision INTEGER NOT NULL CHECK (revision >= 0),
  PRIMARY KEY (item_node_id, field_node_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE github_issue (
  issue_node_id TEXT PRIMARY KEY CHECK (issue_node_id <> ''),
  repository TEXT NOT NULL CHECK (instr(repository, '/') > 1),
  number INTEGER NOT NULL CHECK (number > 0),
  state TEXT NOT NULL CHECK (state IN ('open', 'closed')),
  state_reason TEXT
    CHECK (state_reason IN ('completed', 'not_planned', 'duplicate', 'reopened')),
  baselined INTEGER NOT NULL CHECK (baselined IN (0, 1)),
  revision INTEGER NOT NULL CHECK (revision >= 0)
) STRICT, WITHOUT ROWID;

CREATE TABLE github_dependency (
  blocked_node_id TEXT NOT NULL,
  blocking_node_id TEXT NOT NULL,
  present INTEGER NOT NULL CHECK (present IN (0, 1)),
  revision INTEGER NOT NULL CHECK (revision >= 0),
  PRIMARY KEY (blocked_node_id, blocking_node_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX github_dependency_blocking ON github_dependency (blocking_node_id);

CREATE TABLE github_sub_issue (
  parent_node_id TEXT NOT NULL,
  sub_issue_node_id TEXT NOT NULL,
  present INTEGER NOT NULL CHECK (present IN (0, 1)),
  revision INTEGER NOT NULL CHECK (revision >= 0),
  PRIMARY KEY (parent_node_id, sub_issue_node_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX github_sub_issue_sub ON github_sub_issue (sub_issue_node_id);
ALTER TABLE github_issue ADD COLUMN present INTEGER NOT NULL DEFAULT 1 CHECK (present IN (0, 1));
CREATE TABLE github_card_move (
  actor_id TEXT NOT NULL CHECK (actor_id <> ''),
  invoke_id TEXT NOT NULL CHECK (invoke_id <> ''),
  entry_id TEXT NOT NULL CHECK (entry_id <> ''),
  item_node_id TEXT NOT NULL CHECK (item_node_id <> ''),
  field_node_id TEXT NOT NULL CHECK (field_node_id <> ''),
  option_id TEXT NOT NULL CHECK (option_id <> ''),
  state TEXT NOT NULL CHECK (state IN ('sent', 'confirmed', 'doubtful')),
  sequence INTEGER NOT NULL CHECK (sequence > 0),
  PRIMARY KEY (actor_id, invoke_id, entry_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX github_card_move_field ON github_card_move (item_node_id, field_node_id, sequence);
ALTER TABLE github_issue ADD COLUMN title TEXT;
ALTER TABLE github_issue ADD COLUMN url TEXT;
CREATE TABLE github_project_field (
  project_node_id TEXT NOT NULL CHECK (project_node_id <> ''),
  field_node_id TEXT NOT NULL CHECK (field_node_id <> ''),
  position INTEGER NOT NULL CHECK (position >= 0),
  name TEXT NOT NULL CHECK (name <> ''),
  data_type TEXT NOT NULL
    CHECK (data_type IN ('text', 'number', 'date', 'single-select', 'multi-select', 'iteration')),
  options TEXT NOT NULL CHECK (json_valid(options)),
  PRIMARY KEY (project_node_id, field_node_id)
) STRICT, WITHOUT ROWID;

ALTER TABLE github_project ADD COLUMN fields_read_at INTEGER;

CREATE TABLE github_card_move_next (
  actor_id TEXT NOT NULL CHECK (actor_id <> ''),
  invoke_id TEXT NOT NULL CHECK (invoke_id <> ''),
  entry_id TEXT NOT NULL CHECK (entry_id <> ''),
  item_node_id TEXT NOT NULL CHECK (item_node_id <> ''),
  field_node_id TEXT NOT NULL CHECK (field_node_id <> ''),
  option_id TEXT NOT NULL CHECK (option_id <> ''),
  state TEXT NOT NULL CHECK (state IN ('sent', 'confirmed', 'doubtful')),
  sequence INTEGER NOT NULL CHECK (sequence > 0),
  PRIMARY KEY (actor_id, invoke_id, entry_id, field_node_id, option_id)
) STRICT, WITHOUT ROWID;

INSERT INTO github_card_move_next
  SELECT actor_id, invoke_id, entry_id, item_node_id, field_node_id, option_id, state, sequence
  FROM github_card_move;

DROP TABLE github_card_move;

ALTER TABLE github_card_move_next RENAME TO github_card_move;

CREATE INDEX github_card_move_field ON github_card_move (item_node_id, field_node_id, sequence);

ALTER TABLE ledger_operations RENAME TO ledger_operations_step_one;

CREATE TABLE ledger_operations (
  key TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('credit', 'reserve', 'actual', 'move', 'reattribute')),
  request TEXT NOT NULL,
  at INTEGER NOT NULL
) STRICT;

INSERT INTO ledger_operations SELECT * FROM ledger_operations_step_one;

DROP TABLE ledger_operations_step_one;

ALTER TABLE ledger_entries RENAME TO ledger_entries_step_one;

CREATE TABLE ledger_entries (
  seq INTEGER PRIMARY KEY,
  kind TEXT NOT NULL CHECK (
    kind IN ('credit', 'actual', 'reserve', 'settle', 'move', 'reattribute')
  ),
  operation TEXT,
  account TEXT NOT NULL,
  window_key TEXT,
  item TEXT,
  actor TEXT,
  amount INTEGER NOT NULL,
  at INTEGER NOT NULL,
  CHECK ((kind = 'settle') = (operation IS NULL)),
  CHECK ((kind IN ('credit', 'actual', 'reattribute')) = (window_key IS NOT NULL)),
  CHECK ((kind = 'credit') = (item IS NULL)),
  CHECK ((kind = 'credit') = (actor IS NULL)),
  CHECK (kind <> 'credit' OR amount > 0),
  CHECK (kind <> 'actual' OR amount >= 0),
  CHECK (kind <> 'reserve' OR amount > 0),
  CHECK (kind <> 'settle' OR amount < 0),
  CHECK (kind <> 'move' OR amount <> 0),
  CHECK (kind <> 'reattribute' OR amount <> 0)
) STRICT;

INSERT INTO ledger_entries SELECT * FROM ledger_entries_step_one;

DROP TABLE ledger_entries_step_one;

CREATE INDEX ledger_entries_by_window
  ON ledger_entries (account, window_key, kind);

-- Outstanding reservations: entries of one actor on one item and account.
CREATE INDEX ledger_entries_by_actor
  ON ledger_entries (actor, account, item);

CREATE TRIGGER ledger_operations_no_update
  BEFORE UPDATE ON ledger_operations
  BEGIN SELECT RAISE(ABORT, 'ledger_operations is append-only'); END;

CREATE TRIGGER ledger_operations_no_delete
  BEFORE DELETE ON ledger_operations
  BEGIN SELECT RAISE(ABORT, 'ledger_operations is append-only'); END;

CREATE TRIGGER ledger_entries_no_update
  BEFORE UPDATE ON ledger_entries
  BEGIN SELECT RAISE(ABORT, 'ledger_entries is append-only'); END;

CREATE TRIGGER ledger_entries_no_delete
  BEFORE DELETE ON ledger_entries
  BEGIN SELECT RAISE(ABORT, 'ledger_entries is append-only'); END;

CREATE TABLE router_source_event (
  source TEXT NOT NULL CHECK (source <> ''),
  event_id TEXT NOT NULL CHECK (event_id <> ''),
  accepted_at INTEGER NOT NULL,
  PRIMARY KEY (source, event_id)
) STRICT, WITHOUT ROWID;

-- ---
-- relationships:
--   realizes: t3code-source-database-schema
-- ---
-- SQLite schema of the tables the T3 Code environment source owns in
-- Manifold's database file, migrated under the owner tthree.

CREATE TABLE t3_environment (
  environment TEXT NOT NULL PRIMARY KEY CHECK (environment <> ''),
  environment_id TEXT NOT NULL CHECK (environment_id <> ''),
  origin_sequence INTEGER NOT NULL CHECK (origin_sequence >= 0),
  shell_sequence INTEGER NOT NULL CHECK (shell_sequence >= origin_sequence)
) STRICT, WITHOUT ROWID;

CREATE TABLE t3_thread (
  environment TEXT NOT NULL REFERENCES t3_environment (environment) ON DELETE CASCADE,
  thread_id TEXT NOT NULL CHECK (thread_id <> ''),
  status TEXT NOT NULL CHECK (status IN ('followed', 'archived', 'deleted')),
  cursor INTEGER NOT NULL CHECK (cursor >= 0),
  thread TEXT NOT NULL CHECK (json_valid(thread)),
  PRIMARY KEY (environment, thread_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX t3_thread_followed ON t3_thread (environment, status);
ALTER TABLE t3_thread ADD COLUMN project_id TEXT;
UPDATE t3_thread SET project_id = json_extract(thread, '$.projectId');
ALTER TABLE t3_thread ADD COLUMN attribution TEXT NOT NULL
  DEFAULT '{"turnId":null,"messageId":null,"pendingMessageId":null}'
  CHECK (json_valid(attribution));
CREATE TABLE t3_created_project (
  environment TEXT NOT NULL REFERENCES t3_environment (environment) ON DELETE CASCADE,
  project_id TEXT NOT NULL CHECK (project_id <> ''),
  actor_id TEXT NOT NULL CHECK (actor_id <> ''),
  item TEXT NOT NULL CHECK (item <> ''),
  PRIMARY KEY (environment, project_id)
) STRICT, WITHOUT ROWID;
